/bin/zsh -lc "python3 - <<'PY'
import json,urllib.request,urllib.error
B='http://127.0.0.1:18081'
def req(path,body,key,method='POST'):
 h={'X-Tenant':'t1','Idempotency-Key':key,'Content-Type':'application/json'}
 q=urllib.request.Request(B+path,data=body,headers=h,method=method)
 try:
  with urllib.request.urlopen(q) as r:return r.status,json.loads(r.read())
 except urllib.error.HTTPError as e:return e.code,json.loads(e.read())
for path,body,key in [('/transfers',b'null','concurrent'),('/transfers',b'','concurrent'),('/batches',b'not-json','concurrent')]:
 s,v=req(path,body,key); assert s==409 and v['error']['code']=='idempotency_conflict',(s,v)
for path,body,key in [('/transfers',b'null','fresh-null'),('/transfers',b'[]','fresh-array'),('/transfers',b'','fresh-empty')]:
 s,v=req(path,body,key); assert s==400 and v['error']['code']=='invalid',(s,v)
s,v=req('/totally-unknown',b'{}','concurrent'); assert s==409 and v['error']['code']=='idempotency_conflict',(s,v)
q=urllib.request.Request(B+'/entries?after=0&after=1',headers={'X-Tenant':'t1'})
try: urllib.request.urlopen(q); raise AssertionError('duplicate query accepted')
except urllib.error.HTTPError as e: assert e.code==400
print('strict object and key-conflict checks passed')
PY"
